// dusty-quote-mainnet — signs DustyRecycler v2 quotes on Base MAINNET (chainId 8453).
// Separate Worker script from the testnet one, so testnet keeps running unchanged.
//   * Secret:   QUOTE_SIGNER_KEY_MAINNET  (generated by Hark; never in the repo)
//   * Variable: RECYCLER_V2               (the mainnet recycler address from deploy-mainnet.html)
//   * Variable: DUSTY_POOL                (the Uniswap v3 DUSTY/USDC pool from seed-pool.html; optional)
//   * Optional: TWAP_SECONDS (default 1800, allowed 600-3600), RPC_URL (default https://mainnet.base.org)
//   * Fails closed: no key, wrong key, or no recycler → 503, nothing is signed.
//   * Only the v2 recycler, only allowlisted tokens, only dust (< $10), only if the user holds the amount.
//   * CORS: https://statxqo-clickit.github.io only. Rate limiting: Cloudflare dashboard rule (not in code).
//
// Pricing (market based):
//   dust USD   = amount × price. USDC is fixed at $1. Other allowlisted Base tokens: DefiLlama coins API.
//   DUSTY USD  = 30-minute TWAP of the DUSTY/USDC v3 pool (pool.observe). No DUSTY_POOL set → fixed $0.001.
//                Pool set but TWAP unavailable, or TWAP vs spot differs by more than 20% → no quote (503).
//   dustyOut   = dust USD / DUSTY USD (before fee; the contract takes feeBps), capped at recycler.maxDustyPerQuote().
import { Wallet, JsonRpcProvider, Contract, getAddress } from "ethers";

export const CHAIN_ID = 8453;
const DEFAULT_RPC = "https://mainnet.base.org";
const EXPECTED_SIGNER = "0xE3ed6685AcB201EB40370d181766424C00F2515f";
export const USDC = "0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913";
export const E18 = 10n ** 18n;
export const FIXED_PRICE_1E18 = 10n ** 15n;   // $0.001 per DUSTY (1,000 DUSTY per $1) when no pool is configured
export const MAX_DEVIATION_BPS = 2000;         // 20% TWAP vs spot
export const DEFAULT_TWAP = 1800;              // 30 minutes
const MAX_USD_1E18 = 10n * E18;                // dust = under $10 per quote
const QUOTE_TTL = 600;                         // seconds (contract hard limit 900)
const LLAMA = "https://coins.llama.fi/prices/current/";
const LLAMA_MAX_AGE = 3600, LLAMA_MIN_CONF = 0.9;
const ORIGINS = ["https://statxqo-clickit.github.io"];
const TYPES = { Quote: [
  { name: "user", type: "address" }, { name: "token", type: "address" }, { name: "amount", type: "uint256" },
  { name: "dustyOut", type: "uint256" }, { name: "feeBps", type: "uint16" }, { name: "nonce", type: "uint256" },
  { name: "deadline", type: "uint256" } ] };
const REC_ABI = ["function nonces(address) view returns (uint256)", "function feeBps() view returns (uint16)",
  "function allowedToken(address) view returns (bool)", "function paused() view returns (bool)",
  "function dusty() view returns (address)", "function maxDustyPerQuote() view returns (uint256)"];
const POOL_ABI = ["function token0() view returns (address)", "function token1() view returns (address)",
  "function slot0() view returns (uint160 sqrtPriceX96,int24 tick,uint16,uint16,uint16,uint8,bool)",
  "function observe(uint32[]) view returns (int56[] tickCumulatives,uint160[])"];
const ERC_ABI = ["function balanceOf(address) view returns (uint256)", "function decimals() view returns (uint8)"];

export class QuoteError extends Error { constructor(msg, status = 503) { super(msg); this.status = status; } }

// ---------- pure helpers (unit tested) ----------
/** Average tick over the window, rounded toward negative infinity (same as Uniswap's OracleLibrary.consult). */
export function twapTick(cumOld, cumNew, secs) {
  const d = BigInt(cumNew) - BigInt(cumOld), s = BigInt(secs);
  let t = d / s; if (d < 0n && d % s !== 0n) t -= 1n; return Number(t);
}
/** USD per 1 DUSTY as a float, from a pool tick. DUSTY 18 dp, USDC 6 dp. price(token1/token0) = 1.0001^tick in raw units. */
export function tickToUsdPerDusty(tick, dustyIs0) {
  const raw = Math.pow(1.0001, tick);
  return dustyIs0 ? raw * 1e12 : 1e12 / raw;
}
export const toE18 = (x) => { if (!(x > 0) || !Number.isFinite(x)) throw new QuoteError("bad price"); return BigInt(Math.round(x * 1e18)); };
/** |a-b|/b in bps, using ticks: price ratio = 1.0001^(tickA-tickB). Direction-free. */
export function deviationBps(tickA, tickB) { return Math.round(Math.abs(Math.pow(1.0001, tickA - tickB) - 1) * 10000); }
/** DUSTY units (pre-fee) for a USD value, capped at the per-quote limit. */
export function payout(usd1e18, price1e18, maxPerQuote) {
  if (price1e18 <= 0n) throw new QuoteError("bad price");
  let out = (usd1e18 * E18) / price1e18, capped = false;
  if (maxPerQuote !== undefined && maxPerQuote !== null && out > maxPerQuote) { out = maxPerQuote; capped = true; }
  return { dustyOut: out, capped };
}
export function twapSeconds(env) {
  const n = Number(env.TWAP_SECONDS || DEFAULT_TWAP);
  return Number.isInteger(n) && n >= 600 && n <= 3600 ? n : DEFAULT_TWAP;
}

// ---------- on-chain / API pricing ----------
/** DUSTY price in USD (1e18 fixed). */
export async function priceDusty(provider, poolAddr, dusty, secs) {
  if (!poolAddr) return { price1e18: FIXED_PRICE_1E18, source: "fixed" };
  const pool = new Contract(poolAddr, POOL_ABI, provider);
  let t0, t1, s0, obs;
  try { [t0, t1, s0] = await Promise.all([pool.token0(), pool.token1(), pool.slot0()]); }
  catch { throw new QuoteError("price unavailable (pool unreachable)"); }
  const a = getAddress(t0), b = getAddress(t1), d = getAddress(dusty), u = getAddress(USDC);
  if (!((a === d && b === u) || (a === u && b === d))) throw new QuoteError("price unavailable (pool is not DUSTY/USDC)");
  const dustyIs0 = a === d;
  try { obs = await pool.observe([secs, 0]); }
  catch { throw new QuoteError("price unavailable (pool TWAP not ready yet)"); }
  const tw = twapTick(obs.tickCumulatives[0], obs.tickCumulatives[1], secs), spot = Number(s0.tick);
  const dev = deviationBps(tw, spot);
  if (dev > MAX_DEVIATION_BPS) throw new QuoteError("price moving too fast, try again later");
  const px = tickToUsdPerDusty(tw, dustyIs0);
  return { price1e18: toE18(px), source: "twap", twapTick: tw, spotTick: spot, deviationBps: dev, spot1e18: toE18(tickToUsdPerDusty(spot, dustyIs0)) };
}
/** USD value (1e18 fixed) of `amount` units of `token`. USDC = $1; everything else from DefiLlama. */
export async function priceDust(token, amount, decimals, fetchFn = fetch) {
  const unit = 10n ** BigInt(decimals);
  if (getAddress(token) === getAddress(USDC)) return { usd1e18: (amount * E18) / unit, usd: 1, source: "fixed-usdc" };
  let j;
  try { const r = await fetchFn(LLAMA + "base:" + getAddress(token)); if (!r.ok) throw 0; j = await r.json(); }
  catch { throw new QuoteError("dust price unavailable", 502); }
  const c = Object.entries((j && j.coins) || {}).find(([k]) => k.toLowerCase() === ("base:" + token).toLowerCase());
  const p = c && c[1];
  if (!p || !(p.price > 0)) throw new QuoteError("dust price unavailable", 502);
  if ((p.confidence ?? 0) < LLAMA_MIN_CONF) throw new QuoteError("dust price not reliable", 502);
  if (!p.timestamp || Date.now() / 1000 - p.timestamp > LLAMA_MAX_AGE) throw new QuoteError("dust price stale", 502);
  return { usd1e18: (amount * toE18(p.price)) / unit, usd: p.price, source: "defillama" };
}

// ---------- worker ----------
function cors(req) {
  const o = req.headers.get("Origin") || "";
  return { "Access-Control-Allow-Origin": ORIGINS.includes(o) ? o : ORIGINS[0], "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type", "Vary": "Origin", "Content-Type": "application/json", "Cache-Control": "no-store" };
}
const json = (req, body, status = 200) => new Response(JSON.stringify(body), { status, headers: cors(req) });

function setup(env) {
  let signer = null, recycler = null, pool = null, poolBad = false;
  try { if (env.QUOTE_SIGNER_KEY_MAINNET) signer = new Wallet(env.QUOTE_SIGNER_KEY_MAINNET); } catch { signer = null; }
  if (signer && signer.address !== getAddress(EXPECTED_SIGNER)) signer = null; // wrong key: fail closed
  try { if (env.RECYCLER_V2) recycler = getAddress(env.RECYCLER_V2); } catch { recycler = null; }
  if (env.DUSTY_POOL) { try { pool = getAddress(env.DUSTY_POOL); } catch { poolBad = true; } } // set but invalid: refuse
  return { signer, recycler, pool, poolBad };
}

export default {
  async fetch(req, env) {
    if (req.method === "OPTIONS") return new Response(null, { headers: cors(req) });
    const url = new URL(req.url);
    const { signer, recycler, pool, poolBad } = setup(env);
    const secs = twapSeconds(env);
    if (url.pathname === "/health")
      return json(req, { ok: !!(signer && recycler && !poolBad), signer: signer ? signer.address : null, recyclerV2: recycler, chainId: CHAIN_ID,
        testnet: false, pricing: poolBad ? "bad-pool" : pool ? "twap" : "fixed", pool, twapSeconds: secs });
    if (url.pathname === "/price" && req.method === "GET") {
      if (!recycler || poolBad) return json(req, { error: "quote service not ready" }, 503);
      try {
        const provider = new JsonRpcProvider(env.RPC_URL || DEFAULT_RPC, CHAIN_ID, { staticNetwork: true });
        const dusty = await new Contract(recycler, REC_ABI, provider).dusty();
        const p = await priceDusty(provider, pool, dusty, secs);
        return json(req, { usdPerDusty: Number(p.price1e18) / 1e18, dustyPerUsd: Number((E18 * E18) / p.price1e18) / 1e18, source: p.source, deviationBps: p.deviationBps ?? null });
      } catch (e) { return json(req, { error: e instanceof QuoteError ? e.message : "network busy, try again" }, e instanceof QuoteError ? e.status : 502); }
    }
    if (url.pathname !== "/quote" || req.method !== "POST") return json(req, { error: "not found" }, 404);
    if (!signer || !recycler || poolBad) return json(req, { error: "quote service not ready" }, 503);

    let b; try { b = await req.json(); } catch { return json(req, { error: "bad json" }, 400); }
    let user, token, amount, rec;
    try { user = getAddress(b.user); token = getAddress(b.token); amount = BigInt(b.amount); rec = getAddress(b.recycler || recycler); }
    catch { return json(req, { error: "bad params" }, 400); }
    if (rec !== recycler) return json(req, { error: "unknown recycler" }, 400);
    if (amount <= 0n) return json(req, { error: "zero amount" }, 400);

    let nonce, feeBps, maxPer, dustP, dustyP;
    try {
      const provider = new JsonRpcProvider(env.RPC_URL || DEFAULT_RPC, CHAIN_ID, { staticNetwork: true });
      const r = new Contract(recycler, REC_ABI, provider);
      const erc = new Contract(token, ERC_ABI, provider);
      let allowed, paused, bal, dec, dusty;
      [nonce, feeBps, allowed, paused, bal, maxPer, dusty] = await Promise.all([r.nonces(user, { blockTag: "latest" }), r.feeBps(), r.allowedToken(token),
        r.paused(), erc.balanceOf(user), r.maxDustyPerQuote(), r.dusty()]);
      if (paused) return json(req, { error: "recycling is paused" }, 503);
      if (!allowed) return json(req, { error: "token not supported yet" }, 400);
      if (bal < amount) return json(req, { error: "insufficient balance" }, 400);
      dec = getAddress(token) === getAddress(USDC) ? 6 : Number(await erc.decimals());
      [dustP, dustyP] = await Promise.all([priceDust(token, amount, dec), priceDusty(provider, pool, dusty, secs)]);
    } catch (e) {
      if (e instanceof QuoteError) return json(req, { error: e.message }, e.status);
      return json(req, { error: "network busy, try again" }, 502);
    }
    if (dustP.usd1e18 >= MAX_USD_1E18) return json(req, { error: "not dust (over $10)" }, 400);
    const { dustyOut, capped } = payout(dustP.usd1e18, dustyP.price1e18, maxPer);
    if (dustyOut <= 0n) return json(req, { error: "amount too small" }, 400);
    const deadline = BigInt(Math.floor(Date.now() / 1000) + QUOTE_TTL);
    const domain = { name: "DustyRecycler", version: "2", chainId: CHAIN_ID, verifyingContract: recycler };
    const signature = await signer.signTypedData(domain, TYPES, { user, token, amount, dustyOut, feeBps: Number(feeBps), nonce, deadline });
    const fee = (dustyOut * BigInt(feeBps)) / 10000n;
    return json(req, { user, token, amount: amount.toString(), dustyOut: dustyOut.toString(), toUser: (dustyOut - fee).toString(),
      fee: fee.toString(), feeBps: Number(feeBps), nonce: nonce.toString(), deadline: deadline.toString(), signature,
      recycler, version: 2, chainId: CHAIN_ID, testnet: false,
      pricing: { dustUsd: (Number(dustP.usd1e18) / 1e18).toFixed(6), usdPerDusty: Number(dustyP.price1e18) / 1e18, source: dustyP.source, dustSource: dustP.source, capped } });
  },
};
